-- =============================================================================
-- University of Nigeria, Nsukka — Faculty of Social Sciences — Social Work
-- Course outlines transcribed from the Faculty of Social Sciences course
-- handbook (scanned copy), covering the Four-Year Standard Degree Programme
-- in Social Work: all four years, both semesters, including required
-- ancillary, general-studies and elective courses.
-- =============================================================================
-- Run in the Supabase SQL Editor. Safe to run more than once: existing rows
-- for this department are removed first, so it updates rather than duplicates.
--
-- SEMESTERS: the handbook explicitly labels every course "FIRST SEMESTER" or
-- "SECOND SEMESTER" in its programme-structure tables, so those stated values
-- are used directly — no guessing was needed here.
--
-- ANCILLARY/GSP/ELECTIVE COURSES FROM OTHER DEPARTMENTS: courses such as
-- ANTH 102, SOC 101/102/221, ECO 101/102, PSC 101/102, PSY 101/104/241/251/352,
-- RCS 101/142, GSP 1xx/2xx, COS 101/314, FSS 201/202 and CED 341/342 appear
-- in the Social Work timetable but their own descriptions are not printed in
-- the Social Work section of this document, so they carry real code/title/
-- units only, description left blank pending a verified source elsewhere in
-- this app.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Social Work';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name)
values
  ('SWK 101', 'Introduction to Social Work and Social Welfare', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'first', 2, 'Introduction to the concepts and theories of Social Work Practice. Understanding social problems affecting people and the application of theories and concepts to intervention. A study of the development of social work and values of social work in Europe, America and Nigeria. Survey of the principles and values of the theories of human behaviour especially for social work, concept, relation of social work to other sciences.', '["Introduction to the concepts and theories of Social Work Practice", "Understanding social problems affecting people and the application of theories and concepts to intervention", "A study of the development of social work and values of social work in Europe, America and Nigeria", "Survey of the principles and values of the theories of human behaviour especially for social work, concept, relation of social work to other sciences"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 111', 'Communication in Social Work', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'first', 2, 'Introducing the art of interviewing. The study of skills and techniques required in social work intervention, principles and skills in recording; Various forms of recording; adaptation of interviewing skills in fieldwork practice. Social work recording in various settings such as health and welfare agencies.', '["Introducing the art of interviewing", "The study of skills and techniques required in social work intervention, principles and skills in recording", "Various forms of recording; adaptation of interviewing skills in fieldwork practice", "Social work recording in various settings such as health and welfare agencies"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 121', 'Social Deviance and Systems Organisation', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'first', 2, 'The course sets out to examine the nature, sociological and social work perspectives. The stress will be placed on clandestine subculture identity formation, stereotypes and implications for system or subculture norms and values, bureaucratic conformity and internal norms and discussed. Modules are taught on violence and aggression, characteristic of subculture systems and group solidarity; and structural makeup of individuals and factors, Sociological, environmental, biological, psychological risk on the mental determinants of behaviour and its effects, processes and interpretations, as well as the sociological and cognitive, Attitudinal and behavioural change outcomes and benefits will be stressed from the social work perspectives.', '["The course sets out to examine the nature, sociological and social work perspectives", "The stress will be placed on clandestine subculture identity formation, stereotypes and implications for system or subculture norms and values, bureaucratic conformity and internal norms and discussed", "Modules are taught on violence and aggression, characteristic of subculture systems and group solidarity; and structural makeup of individuals and factors", "Sociological, environmental, biological, psychological risk on the mental determinants of behaviour and its effects, processes and interpretations", "Attitudinal and behavioural change outcomes and benefits will be stressed from the social work perspectives"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 141', 'Fieldwork Orientation', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'first', 4, 'Field work is the core of social work professional education. Students are introduced to the various settings where they meet varieties of clients eg, the Borstal or old peoples home, the prisons, the rehabilitation centers, beggars Project/Emene, welfare centre, etc to get acquainted with the course. After these visits, students are expected to write reports based on their findings and be able to discuss these findings through class presentations seminars and term papers. Students write reports and share their experiences through an interactive forum.', '["Field work is the core of social work professional education", "Students are introduced to the various settings where they meet varieties of clients eg, the Borstal or old peoples home, the prisons, the rehabilitation centers, beggars Project/Emene, welfare centre, etc to get acquainted with the course", "After these visits, students are expected to write reports based on their findings and be able to discuss these findings through class presentations seminars and term papers"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 102', 'Human Behaviour and the Social Environment', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'second', 3, 'This course is intended to introduce students to the basic concepts and models of how human behaviour is shaped, changed and modified in the social environment through the life cycle. Contents should include the knowledge and understanding of normal human development and theories of human behaviour and the range of social systems, including cultural systems, as knowledge base for practice and intervention with individuals, families, communities, groups, organizations and institutions of the society. There is need to emphasize how these systems interact, affect or be affected by human behaviour. The impact of social and economic forces on individuals and social systems and the ways in which systems promote or deter people in achieving and maintaining optimal health and well being will be explored. A broad range of theories relating to the biological, psychological, social development, cognitive, gender, family group, class and race and traditional development models like Piaget, Erickson, Kohlberg, etc as well as values and ethical issues related to them, need to be explored. Students should also be taught to evaluate these theories and apply them to client''s situations.', '["This course is intended to introduce students to the basic concepts and models of how human behaviour is shaped, changed and modified in the social environment through the life cycle", "Knowledge and understanding of normal human development and theories of human behaviour and the range of social systems, including cultural systems, as knowledge base for practice and intervention", "There is need to emphasize how these systems interact, affect or be affected by human behaviour", "The impact of social and economic forces on individuals and social systems and the ways in which systems promote or deter people in achieving and maintaining optimal health and well being", "A broad range of theories relating to the biological, psychological, social development, cognitive, gender, family group, class and race and traditional development models like Piaget, Erickson, Kohlberg, etc"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 122', 'Philosophy and Ethics of Social Work', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'second', 2, 'This course examines the characteristics of the social work profession. It provides the philosophical foundation of the nature of man, contemporary social issues and problems. It considers the principles that are the basis for social work practice and the values and ethics with which social workers must contend within their professional practice.', '["This course examines the characteristics of the social work profession", "It provides the philosophical foundation of the nature of man, contemporary social issues and problems", "It considers the principles that are the basis for social work practice and the values and ethics with which social workers must contend within their professional practice"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 142', 'Introduction to Fieldwork', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'second', 4, 'The course introduces students to the following: areas of practice: need for fieldwork practice, relationship between field and classroom, situational learning objectives of field work and fieldwork recording framework.', '["The course introduces students to the following: areas of practice: need for fieldwork practice", "Relationship between field and classroom, situational learning objectives of field work", "Fieldwork recording framework"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 201', 'Social Work Theory', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'first', 2, 'Basic theories in the practice of social work; its philosophy, purpose and methods; professional intervention through various tools and techniques of problem solving relevant to the Nigerian situation; case-work, community work, problem solving; Social Work like Systems Theory, Crisis Intervention, Behaviour Modification, Role Theory, and Sociological Theories.', '["Basic theories in the practice of social work; its philosophy, purpose and methods", "Professional intervention through various tools and techniques of problem solving relevant to the Nigerian situation; case-work, community work, problem solving", "Social Work like Systems Theory, Crisis Intervention, Behaviour Modification, Role Theory, and Sociological Theories"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 203', 'Elements of Scientific Thought for Social Workers', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'first', 2, 'The course explores scientific methods in contradiction to common sense, indigenous knowledge and the needs of social workers. It is designed to help students acquire the level of objectivity and critical analytical skills that are necessary to design and prosecute empirical research, and to function in aspects of practical social work where such empirical knowledge is needed. Both the historical background and the contemporary issues in the subject are considered. Modules covered are: Origin of scientific thought, options in knowledge production and distribution, and using empiricism, constructs, hypotheses and theories, qualitative and quantitative strategies in scientific method, positivism and socio-cultural factors in scientific method.', '["The course explores scientific methods in contradiction to common sense, indigenous knowledge and the needs of social workers", "It is designed to help students acquire the level of objectivity and critical analytical skills that are necessary to design and prosecute empirical research", "Both the historical background and the contemporary issues in the subject are considered", "Modules covered are: Origin of scientific thought, options in knowledge production and distribution, using empiricism, constructs, hypotheses and theories, qualitative and quantitative strategies in scientific method, positivism and socio-cultural factors in scientific method"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 214', 'Death, Loss and Grief', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'second', 2, 'This course will address the theoretical framework of human loss and grief and how it may be culturally diverse. Students will be provided with information about why and how humans grieve and how grieving is affected by type of loss, socioeconomic and cultural factors, individual personality and family dynamics. Attention will be focused on life span development and the meaning of death and loss at different ages. Various types of loss will be discussed from a national and socio/cultural perspective. The importance of understanding trauma and its relationship to grief and loss will also be addressed, emphasizing the diversity of human response and focusing on the significance of social groups in integrating loss. The formation and practice of rituals, and diversity in religious and spiritual experience as a component of coping with loss will be discussed.', '["This course will address the theoretical framework of human loss and grief and how it may be culturally diverse", "Students will be provided with information about why and how humans grieve and how grieving is affected by type of loss, socioeconomic and cultural factors, individual personality and family dynamics", "Attention will be focused on life span development and the meaning of death and loss at different ages", "The importance of understanding trauma and its relationship to grief and loss will also be addressed", "The formation and practice of rituals, and diversity in religious and spiritual experience as a component of coping with loss will be discussed"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 224', 'Functions of Social Work', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'second', 2, 'Social Work as an instrument of social change. Primary functions of social work in the Nigerian context, analysis of change in the functions of social work with the proper perspectives to current practices.', '["Social Work as an instrument of social change", "Primary functions of social work in the Nigerian context, analysis of change in the functions of social work with the proper perspectives to current practices"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 228', 'Social Work in Health Care Settings', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'second', 3, 'This course examines Social Work Practice in health care institutions. It will explore the role of the social worker with other professionals in the health care settings. The organizational structure and the administration of the health care system in relation to the social work practice will be examined. Students will address issues of health, illness, disease, trauma, grief and loss with personal attitudes to reflect the coping with these conditions. The strengths, empowerment and how present family preferences and the wellness experience and psychosocial influences, ethical values and economic justice and preferences are highlighted. Students are also exposed to medical social work in a variety of settings such as in-patient and outpatient clinics, home care visits as well as hospital and community based centres.', '["This course examines Social Work Practice in health care institutions", "It will explore the role of the social worker with other professionals in the health care settings", "The organizational structure and the administration of the health care system in relation to the social work practice will be examined", "Students will address issues of health, illness, disease, trauma, grief and loss with personal attitudes to reflect the coping with these conditions", "Students are also exposed to medical social work in a variety of settings such as in-patient and outpatient clinics, home care visits as well as hospital and community based centres"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 231', 'Crime, Delinquency and the Quality of Life', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'first', 2, 'The course distinguishes between crime and delinquency and underscores the nature, dimensions, costs and factors associated with crime and delinquent acts causation. The roles of the criminal justice system – courts, prisons, the police and other correctional institutions and the legal system and extent of social work involvement and contribution in the process. The legal issues and conflicts involved are also explored.', '["The course distinguishes between crime and delinquency and underscores the nature, dimensions, costs and factors associated with crime and delinquent acts causation", "The roles of the criminal justice system – courts, prisons, the police and other correctional institutions", "The legal system and extent of social work involvement and contribution in the process", "The legal issues and conflicts involved are also explored"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 240', 'Social Work with the Youth', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'second', 2, 'The course is designed to provide social workers with skill and competence to practice with the youth. Issues of adolescence and problems associated with it will be discussed. Such problems as juvenile delinquency, substance abuse, teenage pregnancy, sexually transmitted diseases, HIV/AIDS will be given prominence.', '["The course is designed to provide social workers with skill and competence to practice with the youth", "Issues of adolescence and problems associated with it will be discussed", "Such problems as juvenile delinquency, substance abuse, teenage pregnancy, sexually transmitted diseases, HIV/AIDS will be given prominence"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 242', 'Social Work Intervention with Families', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'second', 2, 'The family is taken as the basic unit for social development. The need of children and parents will be examined. Attention will also be given to orphans and vulnerable children and care givers, salutations, institutional provisions needs, etc. Welfare services to meet their needs will be analysed with a view to strengthening, supporting and enabling the family to perform their duties. Special attention will be given to health, nutritional, educational and developmental needs of children and parents, with a view to preserving internal unity and safeguarding the integrity of the family. Institutional support to orphans and vulnerable children will also given full stress.', '["The family is taken as the basic unit for social development. The need of children and parents will be examined", "Attention will also be given to orphans and vulnerable children and care givers, salutations, institutional provisions needs, etc", "Welfare services to meet their needs will be analysed with a view to strengthening, supporting and enabling the family to perform their duties", "Special attention will be given to health, nutritional, educational and developmental needs of children and parents, with a view to preserving internal unity and safeguarding the integrity of the family"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 243', 'Social Work Practice and Gender', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'first', 2, 'This course examines the psychological and sociological approaches to the study of women and the application of these theories to social work practice. Women often do not fit the existing models of human and social development, therefore the course will focus on issues that have been developed for women and critically analyse the related empirical research. Such models as Feminist perspective and women empowerment among others will be covered with special practice issues to be covered include: intervention health, violence, widowhood practices and other harmful traditional practices.', '["This course examines the psychological and sociological approaches to the study of women and the application of these theories to social work practice", "Women often do not fit the existing models of human and social development, therefore the course will focus on issues that have been developed for women and critically analyse the related empirical research", "Such models as Feminist perspective and women empowerment among others will be covered", "Special practice issues to be covered include: intervention health, violence, widowhood practices and other harmful traditional practices"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 244', 'Social Work in Rehabilitation', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'second', 2, 'This course enables students to understand rehabilitation as services that help the handicapped person (physically, mentally, socially, economically etc) have conducive environment and opportunities for the total development of their human potentials. This will be achieved through the following processes: individualized plan for goal achievement, constant assessment and reassessment, programme of services, follow-up and programme evaluation.', '["This course enables students to understand rehabilitation as services that help the handicapped person (physically, mentally, socially, economically etc) have conducive environment and opportunities for the total development of their human potentials", "This will be achieved through the following processes: individualized plan for goal achievement, constant assessment and reassessment, programme of services, follow-up and programme evaluation"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 245', 'Social Work Field Practice: Social Analysis in Casework', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'first', 2, 'The trainees will be provided the opportunities to develop skills to effectively apply generalist knowledge and skills in any social work situation, especially case work, through the following means: Knowing what the agency does and roles of the agency as regards its internal functioning, relationship with external environment, resources and within and outside the agency, understanding the values of social work and observing the supervisor in problem identification, assessment, planning, interviewing and recording. Students interact in participatory class sections to share their experiences from various agencies and equally present seminars, write report on their field experiences and activities under the supervision of the classroom instructor.', '["The trainees will be provided the opportunities to develop skills to effectively apply generalist knowledge and skills in any social work situation, especially case work", "Knowing what the agency does and roles of the agency as regards its internal functioning, relationship with external environment, resources and within and outside the agency", "Understanding the values of social work and observing the supervisor in problem identification, assessment, planning, interviewing and recording", "Students interact in participatory class sections to share their experiences from various agencies and equally present seminars, write report on their field experiences and activities under the supervision of the classroom instructor"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 246', 'Social Work Field Practice: Problem Solving and Evaluation in Case Work', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'second', 3, 'Under the guidance and supervision of the supervisor, students will implement the planned programmes in meeting the client''s needs, focusing on the potentialities within the client and his environment to meet his needs. Practical skills will be facilitated and reinforced in areas of interviewing, case recording, and observation of basic social work values while giving services.', '["Under the guidance and supervision of the supervisor, students will implement the planned programmes in meeting the client''s needs, focusing on the potentialities within the client and his environment to meet his needs", "Practical skills will be facilitated and reinforced in areas of interviewing, case recording, and observation of basic social work values while giving services"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 248', 'Social Work Communication Techniques', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'second', 2, 'This course covers principles and processes of communication, types of communications skills needed to understand human nature in social work, transactional analysis, interviewing services and followed by evaluation. Through class presentations, reporting and seminars students gather more knowledge about a multitude of agencies and clients situations as they share their experiences in the class sessions.', '["This course covers principles and processes of communication, types of communications skills needed to understand human nature in social work, transactional analysis, interviewing services and followed by evaluation", "Through class presentations, reporting and seminars students gather more knowledge about a multitude of agencies and clients situations as they share their experiences in the class sessions"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 251', 'Community Development', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'first', 2, 'The course highlights major community development theories that would guide the social worker in the community. Basic concepts in community development, Historical development of community development initiative. Identifying and meeting various community groups educational enlightenment.', '["The course highlights major community development theories that would guide the social worker in the community", "Basic concepts in community development, Historical development of community development initiative", "Identifying and meeting various community groups educational enlightenment"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 301', 'Orphans and Vulnerable Children Services', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'first', 2, 'The course is designed to equip students with appropriate skills and knowledge to serve the needs of orphans and vulnerable children. This is also intended to prepare them for effective intervention through exposure to the concepts, process and helping skills that underlie all interventions with vulnerable children and families. Thus, a range of psychosocial challenges related to HIV/AIDS and other traumatic and stressful events that underline the interventions with vulnerable children and families will be addressed to include ways to obtain social and institutional support providing counselling stigma, and resources and system 0f care at various levels are stressed.', '["The course is designed to equip students with appropriate skills and knowledge to serve the needs of orphans and vulnerable children", "This is also intended to prepare them for effective intervention through exposure to the concepts, process and helping skills that underlie all interventions with vulnerable children and families", "A range of psychosocial challenges related to HIV/AIDS and other traumatic and stressful events that underline the interventions with vulnerable children and families will be addressed", "Ways to obtain social and institutional support providing counselling stigma, and resources and system of care at various levels are stressed"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 303', 'Social Welfare Programme and Services', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'first', 2, 'A descriptive examination of publicly sponsored programmes and policies in comparison with those rooted in the private sector. The course explores traditional and contemporary problems of the time as they affect the civil society and human functioning in contemporary times. It aims at knowledge of specific Nigerian programmes and the underlying social issues.', '["A descriptive examination of publicly sponsored programmes and policies in comparison with those rooted in the private sector", "The course explores traditional and contemporary problems of the time as they affect the civil society and human functioning in contemporary times", "It aims at knowledge of specific Nigerian programmes and the underlying social issues"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 305', 'Elements of Psychology in Social Work', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'first', 2, 'Theoretical approaches to personality structure; self as a personality attribute, moral dimensions; concept of normality, psychology of adjustment viewed from these dimensions; (a) Criteria for good adjustment; (b) principles of good adjustment, anxiety, frustration, assimilation, competition and conflict, learning theory with emphasis on how it affects behaviour, stress, abnormal psychology and social work perspectives.', '["Theoretical approaches to personality structure; self as a personality attribute, moral dimensions; concept of normality, psychology of adjustment viewed from these dimensions", "Criteria for good adjustment; principles of good adjustment, anxiety, frustration, assimilation, competition and conflict", "Learning theory with emphasis on how it affects behaviour, stress, abnormal psychology and social work perspectives"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 311', 'Social Policy and Planning', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'first', 2, 'This course focuses on introducing students to the knowledge, values and skills required for administration and planning for human services. Types and phases of administration and management will be introduced. Types of social policies and knowledge of various policies will be considered.', '["This course focuses on introducing students to the knowledge, values and skills required for administration and planning for human services", "Types and phases of administration and management will be introduced", "Types of social policies and knowledge of various policies will be considered"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 313', 'Community Mental Health Services', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'first', 2, 'The thrust of this course will be to focus on community health and mental health in general. Attempt should be made to focus on the individual and institutional roles and responsibilities for health, the various dimensions of health, health indicators, community mental health problems and issues. The course also examines the role of the socio-cultural environment in the cause of psychiatric disorders. Services especially to chronic or severe and mild cases of mental disorders and for the low-income populations are to be explored in details.', '["The thrust of this course will be to focus on community health and mental health in general", "Attempt should be made to focus on the individual and institutional roles and responsibilities for health, the various dimensions of health, health indicators, community mental health problems and issues", "The course also examines the role of the socio-cultural environment in the cause of psychiatric disorders", "Services especially to chronic or severe and mild cases of mental disorders and for the low-income populations are to be explored in details"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 320', 'Social Work and Social Problems', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'second', 2, 'The thrust of the course is on the concept of social functioning, social problems and the dynamics of social change, the impact of social change and social problems on individual, community, group and family social functioning. Institutional and structural approaches in the analyses of social problems, determining/causative factors and the impact of social transformations and continuity on traditional institutions.', '["The thrust of the course is on the concept of social functioning, social problems and the dynamics of social change, the impact of social change and social problems on individual, community, group and family social functioning", "Institutional and structural approaches in the analyses of social problems, determining/causative factors", "The impact of social transformations and continuity on traditional institutions"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 322', 'Counselling and Psychotherapy', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'second', 2, 'The student is exposed to the contents and nature of counselling and psychotherapy in a complex multicultural environment such as Nigeria comprehensive. It gives a professional overview of counselling and psychotherapeutic process. Interviewing and assessment skills, methods of evaluation, and recording in the counselling and psychotherapeutic process. In-depth examination of selected theories in counselling and psychotherapy such as behaviour therapy, reality therapy, rational, motive therapy etc. will be discussed. Application of the therapeutic techniques and skills to various settings will also be emphasised.', '["The student is exposed to the contents and nature of counselling and psychotherapy in a complex multicultural environment such as Nigeria comprehensive", "It gives a professional overview of counselling and psychotherapeutic process", "Interviewing and assessment skills, methods of evaluation, and recording in the counselling and psychotherapeutic process", "In-depth examination of selected theories in counselling and psychotherapy such as behaviour therapy, reality therapy, rational, motive therapy etc"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 324', 'Care Management in Social Work Practice', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'second', 2, 'The course examines the knowledge, values and skills provided by professional education and training for social work. It requires coordinating services across a range of field, day and residential settings, drawing on natural, voluntary, private and statutory sources of help. The care management process aims to achieve planned goals using what is familiar and central tasks in social work such as data collection, analyses and intervention.', '["The course examines the knowledge, values and skills provided by professional education and training for social work", "It requires coordinating services across a range of field, day and residential settings, drawing on natural, voluntary, private and statutory sources of help", "The care management process aims to achieve planned goals using what is familiar and central tasks in social work such as data collection, analyses and intervention"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 326', 'Spirituality and Social Work Practice', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'second', 2, 'The course derives its meaning and essence from its religious roots given the profession''s assumption that revolves around understanding the total person in his environmental and cultural contexts. It traces social work historical development and underpins the relationship between religion and spirituality in the context of man''s longing for a sense of meaning from transcendental forces through responsible moral relationships with diverse populations spanning individuals, families, communities as well as cultures and religions. An integrative approach including comparative religious orientations, multidisciplinary approach including anthropology, sociology, psychology and social work will be of essence. This provides a basic background framework to the historical, cultural and religious orientations and philosophy for the course with social work practice. Students should be aware and sensitive to the ethical issues/dilemmas/conflicts and values ever present in the practice milieu. Knowledge, skills and competent interventions are enhanced through practical frameworks derived from individual assignments, practicum visits, class interactive sessions and term paper presentations.', '["The course derives its meaning and essence from its religious roots given the profession''s assumption that revolves around understanding the total person in his environmental and cultural contexts", "It traces social work historical development and underpins the relationship between religion and spirituality in the context of man''s longing for a sense of meaning from transcendental forces through responsible moral relationships with diverse populations", "An integrative approach including comparative religious orientations, multidisciplinary approach including anthropology, sociology, psychology and social work will be of essence", "Students should be aware and sensitive to the ethical issues/dilemmas/conflicts and values ever present in the practice milieu", "Knowledge, skills and competent interventions are enhanced through practical frameworks derived from individual assignments, practicum visits, class interactive sessions and term paper presentations"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 327', 'Rural Social Work', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'first', 2, 'Study of social work potentials in rural areas. The utilization of natural helping networks in isolated areas and the organization of helping linkages in the provision of care to residents.', '["Study of social work potentials in rural areas", "The utilization of natural helping networks in isolated areas and the organization of helping linkages in the provision of care to residents"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 328', 'Dynamics of Social Functioning', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'second', 2, 'Personality growth of the individual in society and culture; social determinants of personality; defence mechanisms of the individual for maintaining normality; personality disorders in the Nigerian context. Motivational patterns in Nigeria, Modification of adaptive and maladaptive responses on motivational processes.', '["Personality growth of the individual in society and culture; social determinants of personality", "Defence mechanisms of the individual for maintaining normality; personality disorders in the Nigerian context", "Motivational patterns in Nigeria, Modification of adaptive and maladaptive responses on motivational processes"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 330', 'Industrial Social Work', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'second', 2, 'The course introduces the student to the industrial/organizational context of social work practice. It examines the structure, nature, purpose and significant trends and events within organizations as well as how these trends respond to workers and organizational needs, employer – employee relationship, and the promoting harmonious relationship within system. Adequate stress will be given to organizational theories and social workers roles in such a context.', '["The course introduces the student to the industrial/organizational context of social work practice", "It examines the structure, nature, purpose and significant trends and events within organizations as well as how these trends respond to workers and organizational needs, employer – employee relationship", "Adequate stress will be given to organizational theories and social workers roles in such a context"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 331', 'Social Work Intervention', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'first', 2, 'This is a laboratory course that should provide opportunities for students to work to refine social work skills and to acquire new ones; small group leadership, chairing meetings, interviewing, reporting and recording activities, community assessment and community organizing as skills.', '["This is a laboratory course that should provide opportunities for students to work to refine social work skills and to acquire new ones; small group leadership, chairing meetings", "Interviewing, reporting and recording activities", "Community assessment and community organizing as skills"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 335', 'Community Development Theory', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'first', 3, 'Community Development theories and principles, processes and programmes of community development: history of community development (in Nigeria). The community development worker as an organiser and leader in the community, economic integration and social development through community development process.', '["Community Development theories and principles, processes and programmes of community development: history of community development (in Nigeria)", "The community development worker as an organiser and leader in the community", "Economic integration and social development through community development process"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 340', 'School Social Work', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'second', 2, 'The study of social work practice in the Nigerian primary, secondary and tertiary instruction. Identification of roles and relationship of social work as a profession within the school system, and with individuals and groups in the school system, intervention strategies and skills appropriate for such areas. Focus on the social worker as practitioner in isolation.', '["The study of social work practice in the Nigerian primary, secondary and tertiary instruction", "Identification of roles and relationship of social work as a profession within the school system, and with individuals and groups in the school system", "Intervention strategies and skills appropriate for such areas. Focus on the social worker as practitioner in isolation"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 341', 'Social Work Practice with Group', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'first', 2, 'The course incorporates both micro and macro elements in focusing on social worker analysis of group development, worker-client interactions and interventions in the helping process. Emphasis is placed on understanding social work skill and theories that help the manage a group.', '["The course incorporates both micro and macro elements in focusing on social worker analysis of group development, worker-client interactions and interventions in the helping process", "Emphasis is placed on understanding social work skill and theories that help the manage a group"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 344', 'Community Education', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'second', 2, 'Identification and assessment of objectives and problems of social development in terms of adult literacy, health education and extension services: the role of social workers in teams members in an integrated approach to development.', '["Identification and assessment of objectives and problems of social development in terms of adult literacy, health education and extension services", "The role of social workers in teams members in an integrated approach to development"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 345', 'Social Work Field Practice (Social Analysis: in Group Work)', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'first', 2, 'This course focuses on orienting students into group behaviour patterns, the subject matter or the task upon which the group is working and what is happening among group members. Awareness of and sensitivity to group dynamics and its importance in analyzing group problems will be emphasised. Students participate interactively and share experiences gathered in their various field work placement agencies. Written reports and seminars including class discussions of their field activities and experiences will be discussed.', '["This course focuses on orienting students into group behaviour patterns, the subject matter or the task upon which the group is working and what is happening among group members", "Awareness of and sensitivity to group dynamics and its importance in analyzing group problems will be emphasised", "Students participate interactively and share experiences gathered in their various field work placement agencies", "Written reports and seminars including class discussions of their field activities and experiences will be discussed"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 346', 'Field Work: Problem Solving and Evaluation in Group Work', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'second', 2, 'This is intended through generalist approach to provide students the opportunities to apply theoretical knowledge empirically in the identification of problems in group people, provide services for people within the group, followed by the evaluation of the services. Students interact and share their experiences through class presentations, seminars and write reports of events and activities in the field under the guidance of the instructor.', '["This is intended through generalist approach to provide students the opportunities to apply theoretical knowledge empirically in the identification of problems in group people, provide services for people within the group, followed by the evaluation of the services", "Students interact and share their experiences through class presentations, seminars and write reports of events and activities in the field under the guidance of the instructor"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 348', 'Social Work with the Elderly', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'second', 2, 'This is a course on the normal aging process, the developmental task of the aged, and theories of aging. The goal is to create a holistic understanding of the aging process by examining old age cultural, economic, physical, environmental, social and psychological influences on old age. Skills required by social workers in dealing with the elderly and their families will be discussed. Issues of care giving, elder abuse and other issues related to the elderly will be highlighted.', '["This is a course on the normal aging process, the developmental task of the aged, and theories of aging", "The goal is to create a holistic understanding of the aging process by examining old age cultural, economic, physical, environmental, social and psychological influences on old age", "Skills required by social workers in dealing with the elderly and their families will be discussed", "Issues of care giving, elder abuse and other issues related to the elderly will be highlighted"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 352', 'Community Needs and Resources Assessment', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'second', 2, 'This course helps student develop skills for assessing community needs and resources necessary for human survival, growth and fulfillment. The students will be required to identify those social needs that are not being met and essential resources absent. The assessment of community needs and resources will be considered.', '["This course helps student develop skills for assessing community needs and resources necessary for human survival, growth and fulfillment", "The students will be required to identify those social needs that are not being met and essential resources absent", "The assessment of community needs and resources will be considered"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 353', 'Social Work and Mental Health', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'first', 2, 'This course is designed to acquaint the students with a historical aetiology, historical movements and efforts towards conceptualizing and understanding, treating, and control in the contemporary times with past experiences. The Nigerian traditional attitudes and beliefs and a comparison with other perspectives that led to the full understanding of mental health must be graphically described. Exploration of psychiatric aetiology and of its treatment, intervention strategies and skills must be examined. The entry of social work among the interdisciplinary treatment tradition should also be historically delineated.', '["This course is designed to acquaint the students with a historical aetiology, historical movements and efforts towards conceptualizing and understanding, treating, and control in the contemporary times with past experiences", "The Nigerian traditional attitudes and beliefs and a comparison with other perspectives that led to the full understanding of mental health must be graphically described", "Exploration of psychiatric aetiology and of its treatment, intervention strategies and skills must be examined", "The entry of social work among the interdisciplinary treatment tradition should also be historically delineated"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 362', 'Methods of Social Work Research', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '300 Level', 'second', 3, 'Scientific principles basic to social work research are examined. Students learn how to formulate problems and hypotheses, develop research designs and methodology, carry out research, and utilize social work research report.', '["Scientific principles basic to social work research are examined", "Students learn how to formulate problems and hypotheses, develop research designs and methodology, carry out research, and utilize social work research report"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 406', 'Models of Family Therapy', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'second', 2, 'Family Therapy models by various social work theorists and application to real life situations. Different problems encountered in the family and various models of intervention.', '["Family Therapy models by various social work theorists and application to real life situations", "Different problems encountered in the family and various models of intervention"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 412', 'Gerontology and Geriatric Interventions in Social Work', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'second', 3, 'The course introduces the need, nature and processes of Social Work with the elderly in the Nigerian society, given the increasing population of the aged and the process of social work. Special focus of the course will be on interventions issues surrounding population aging in Nigeria, social legislation and policies as well as future policy directions on the aged in Nigeria should be explored.', '["The course introduces the need, nature and processes of Social Work with the elderly in the Nigerian society, given the increasing population of the aged and the process of social work", "Special focus of the course will be on interventions issues surrounding population aging in Nigeria, social legislation and policies", "Future policy directions on the aged in Nigeria should be explored"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 413', 'Social Work and the Law', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'first', 2, 'The trust of this course revolves around legal issues and regulation of social work. This includes licensing standard, ethnical issues and sanction, liability of social workers as well as professional liability. Also to be included in the social work involvement in the legal processes as well as testifying in court and documents substantive laws affecting social work practice in special areas such as child abuse, and protection family practice, criminal law, privacy and confidentiality issues in domestic abuse and violence.', '["The trust of this course revolves around legal issues and regulation of social work. This includes licensing standard, ethnical issues and sanction, liability of social workers as well as professional liability", "Social work involvement in the legal processes as well as testifying in court and documents substantive laws affecting social work practice in special areas such as child abuse, and protection family practice, criminal law", "Privacy and confidentiality issues in domestic abuse and violence"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 414', 'Organisational/Administrative Skills and Social Work Practice', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'second', 2, 'This course provides the student with an understanding of organisational behaviour as well as how social agencies operate and function as organizational entities. It equips the student with skills required for effective social work practice interventions within organization, including budgeting, grant writing and elements of supervision.', '["This course provides the student with an understanding of organisational behaviour as well as how social agencies operate and function as organizational entities", "It equips the student with skills required for effective social work practice interventions within organization, including budgeting, grant writing and elements of supervision"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 421', 'International Social Work', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'first', 3, 'The idea of this course is to expose the students to international environment, with a view to preparing and equipping them to be able to practice competently anywhere in the globalize world, be it western or developing societies. This calls into question a close look at inter-cultural contexts and competence, interpersonal interactions and relationships, biases or differences, with respect to cultural patterns and communications, cultural identity, biases or differences, with respect to cultural patterns and communications, cultural identity, and potentials for inter-cultural competent practice. All these will be seen in the light of social work agenda and interests in cultural diversity practice. Concrete examples must be cited from both western and developing world''s cultures. The course further explores the challenges across nations, thus contrasting problem definitions and problem responses among nations at various levels of socioeconomic and political transformations. The course also provides analytical tools on social policies from various nations, while contrasting and identifying the various welfare state transformations among the different nations identified.', '["The idea of this course is to expose the students to international environment, with a view to preparing and equipping them to be able to practice competently anywhere in the globalize world, be it western or developing societies", "This calls into question a close look at inter-cultural contexts and competence, interpersonal interactions and relationships, biases or differences, with respect to cultural patterns and communications, cultural identity, and potentials for inter-cultural competent practice", "Concrete examples must be cited from both western and developing world''s cultures", "The course further explores the challenges across nations, thus contrasting problem definitions and problem responses among nations at various levels of socioeconomic and political transformations", "The course also provides analytical tools on social policies from various nations, while contrasting and identifying the various welfare state transformations among the different nations identified"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 423', 'Substance Abuse, Prevention and Intervention', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'first', 2, 'Exploration of the nature, development and phenomenon of addiction generally. There is need to focus attention on the roles and effects of substances in particular. There is the need for social workers and allied professionals within a team to work with substance abusers will be discussed. Special attention should be given to the roles of mass policies, societal and the supports required for intervention and prevention strategies.', '["Exploration of the nature, development and phenomenon of addiction generally. There is need to focus attention on the roles and effects of substances in particular", "There is the need for social workers and allied professionals within a team to work with substance abusers will be discussed", "Special attention should be given to the roles of mass policies, societal and the supports required for intervention and prevention strategies"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 431', 'Ethno-Cultural Relations and the Nigerian State', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'first', 2, 'The essence of this course is to expand student''s horizon of knowledge and understanding of the meaning of ethnicity, culture, class, and gender as well as the concepts of marginalisation, oppression, stigma, prejudice and stereotyping. This prepares a good ground for students to practice in a multi-ethnic society like Nigeria. Since the issues around personal, professional, institutional and social levels and national outlook, a comprehensive analysis of ethnic issues in Nigeria are required: politics governance, resource control, quota system, religious, gender, conflict and lopsided development. Students are worth an approach that supports and enhances the culture of the people. Students are also expected to adopt an integrative perspective and explore the implications for both direct and indirect social work practice, given the Nigerian experience.', '["The essence of this course is to expand student''s horizon of knowledge and understanding of the meaning of ethnicity, culture, class, and gender as well as the concepts of marginalisation, oppression, stigma, prejudice and stereotyping", "This prepares a good ground for students to practice in a multi-ethnic society like Nigeria", "A comprehensive analysis of ethnic issues in Nigeria are required: politics governance, resource control, quota system, religious, gender, conflict and lopsided development", "Students are also expected to adopt an integrative perspective and explore the implications for both direct and indirect social work practice, given the Nigerian experience"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 434', 'Social Work Legislation and Policy', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'second', 3, 'The nature and development of social welfare policy in Nigeria, legal and governmental processes of social policy and planning as well as decision making. Social legislation in Nigeria; family law, children and young persons'' law, adoption law, etc; principles underlying social agency policy and function. Social workers role in administering and coordinating social welfare programmes; nature of client system and rights of the clients.', '["The nature and development of social welfare policy in Nigeria, legal and governmental processes of social policy and planning as well as decision making", "Social legislation in Nigeria; family law, children and young persons'' law, adoption law, etc; principles underlying social agency policy and function", "Social workers role in administering and coordinating social welfare programmes; nature of client system and rights of the clients"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 441', 'Methods of Social Work Practice', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'first', 2, 'This course helps students develop and demonstrate understanding of and utilise interpersonal skills in social work treatment. It focuses on communication and the helping relationship and factors affecting them. It assists students in developing the capacity to identify the factors that affect changes in the relationship between the social system and the clients.', '["This course helps students develop and demonstrate understanding of and utilise interpersonal skills in social work treatment", "It focuses on communication and the helping relationship and factors affecting them", "It assists students in developing the capacity to identify the factors that affect changes in the relationship between the social system and the clients"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 442', 'Generalist Approach in Social Work Practice', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'second', 2, 'This course helps students to develop practice skill within a theoretical framework. The major emphasis is on problem solving. The students are assisted to develop the capacity for assessment and the use of intervention strategies according to psychological, problem-solving and behavioural approaches. Students will also develop the capacity to observe, analyse and utilise groups for therapeutic purpose.', '["This course helps students to develop practice skill within a theoretical framework. The major emphasis is on problem solving", "The students are assisted to develop the capacity for assessment and the use of intervention strategies according to psychological, problem-solving and behavioural approaches", "Students will also develop the capacity to observe, analyse and utilise groups for therapeutic purpose"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 444', 'Forensic Social Work', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'second', 2, 'The Course examines the services provided for prisoners/person in detention in the prisons. It traces the origin of prison (world and Nigeria), the history of social work services in the prisons, reforms in the services provided, factors affecting the services provided etc.', '["The Course examines the services provided for prisoners/person in detention in the prisons", "It traces the origin of prison (world and Nigeria), the history of social work services in the prisons", "Reforms in the services provided, factors affecting the services provided etc"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 445', 'Field Practice (Social Analysis in Community Organization)', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'first', 4, 'This course will provide students the opportunity to apply their theoretical knowledge about their understanding of how communities function in concrete situations in communities and community development agencies. Class participation, seminar presentation and reports under the guidance of the classroom instructor as students share experiences and demonstrate their skills and competencies in handling cases and situations in their placement agencies.', '["This course will provide students the opportunity to apply their theoretical knowledge about their understanding of how communities function in concrete situations in communities and community development agencies", "Class participation, seminar presentation and reports under the guidance of the classroom instructor as students share experiences and demonstrate their skills and competencies in handling cases and situations in their placement agencies"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 446', 'Field Practice (Problem Solving and Evaluation in Community Organisation)', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'second', 3, 'Having acquired theoretical knowledge of problem solving, students will be assisted to apply this knowledge in solving and evaluating concrete problems in community setting. Students'' participation, seminar presentation and reports under the supervision of the classroom instructor as the students engage and share experiences and demonstrate their skills and knowledge in handling cases from their various agencies.', '["Having acquired theoretical knowledge of problem solving, students will be assisted to apply this knowledge in solving and evaluating concrete problems in community setting", "Students'' participation, seminar presentation and reports under the supervision of the classroom instructor as the students engage and share experiences and demonstrate their skills and knowledge in handling cases from their various agencies"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 447', 'Social Work Practice with Children', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'first', 2, 'This course is intended to prepare students for effective practice with children. The course provides a comprehensive review of child development; review of major concerns that social workers may effectively promote successful evaluation and treatment of children and the acquisition of psychosocial competence that will focus on the development of knowledge and skill to prepare professional social workers for position in child welfare agencies.', '["This course is intended to prepare students for effective practice with children. The course provides a comprehensive review of child development", "Review of major concerns that social workers may effectively promote successful evaluation and treatment of children and the acquisition of psychosocial competence", "This will focus on the development of knowledge and skill to prepare professional social workers for position in child welfare agencies"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 451', 'Community Development Practice', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'first', 3, 'Application of the principles of community development in assisting communities carry out development projects, locating and meeting community needs through local groups; the community organiser''s involvement in programmes of public enlightenment; methods of community organiser and social action through community development as radical movement for social change.', '["Application of the principles of community development in assisting communities carry out development projects, locating and meeting community needs through local groups", "The community organiser''s involvement in programmes of public enlightenment; methods of community organiser and social action through community development as radical movement for social change"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 454', 'Clinical Social Work Practice, Psychopathology and Trauma', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'second', 3, 'This course is designed to boost student''s clinical competence through knowledge and skills development as well as familiarisation with the basic concepts and principles of clinical practice. The basis for intervention borders on the systemic differential assessment of human problems in the social context. Particular attention is paid on the use of self, the environment, the group and activities differentially while working with different processes, populations, settings and the problems or issues of concern. In addition, reference to life cycle issues, gender, culture, class or status as well as the social and environmental stressors is to be highlighted. A comprehensive understanding of psychopathology and issues as well as various conceptualizations of trauma, clinical strategies and interventions with diverse populations are of essence. Diagnostic issues, evidence based interventions, controversies and emerging trends and area of practice with victims are to be underscored. The social, political cultural and economic forces perpetuating and shaping the sources of exposure, as well as recovering from traumatic stressors and events are to be equally explored. Service delivery systems design, import of ethno-cultural competent practice, strategies and goals for self care and trauma impact on clinicians as well as burn out reduction are also central to the theme of the course.', '["This course is designed to boost student''s clinical competence through knowledge and skills development as well as familiarisation with the basic concepts and principles of clinical practice", "The basis for intervention borders on the systemic differential assessment of human problems in the social context", "A comprehensive understanding of psychopathology and issues as well as various conceptualizations of trauma, clinical strategies and interventions with diverse populations are of essence", "Diagnostic issues, evidence based interventions, controversies and emerging trends and area of practice with victims are to be underscored", "Service delivery systems design, import of ethno-cultural competent practice, strategies and goals for self care and trauma impact on clinicians as well as burn out reduction"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 491', 'Project Tutorials', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'first', 1, 'Students meet with the supervisors regularly to discuss basic issues, principles and orientation of project writing. Assessment of the student and grading are in respect of zeal, orientation, objectivity and ability to follow guided instruction and corrections agreed upon on submission of chapters of unit.', '["Students meet with the supervisors regularly to discuss basic issues, principles and orientation of project writing", "Assessment of the student and grading are in respect of zeal, orientation, objectivity and ability to follow guided instruction and corrections agreed upon on submission of chapters of unit"]'::jsonb, 'Department of Social Work handbook'),
  ('SWK 492', 'Project Report', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '400 Level', 'second', 6, 'An original research project report on an approved topic on social work and community development basis on field practice in field experience or library research is submitted and evaluated.', '["An original research project report on an approved topic on social work and community development basis on field practice in field experience or library research is submitted and evaluated"]'::jsonb, 'Department of Social Work handbook'),
  -- Required ancillary / general studies / elective courses from other departments — real code/title/units from the timetable, description left blank pending a verified source.
  ('ANTH 102', 'Introduction to Anthropology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'first', 4, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('SOC 101', 'Introduction to Sociology I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('GSP 101', 'The Use of English', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'first', 2, 'Man, Society and Language - The Nature, Characteristics and Functions of Language, Human Communication & Language, The English Language and the Nigerian society, World English, Levels and Varieties of English — formal, informal, standard, etc., English in Literature and the Media.

Vocabulary of English - Types, Method of Vocabulary Development, Synonyms, Antonyms, Homonyms, Acronyms, Paronyms, Affixation and other morphological processes, English Language Register, diatypes and dialects.

Listening skill - The listening skill discussed as a receptive and reciprocal activity, Nature, Types, Purposes and Factors that affect Listening, Strategies and Aids for Effective Listening.

Reading Skill - The concept of reading as a linguistic organization and a vehicle of communication. Reading Problems, Levels of Reading, Types of Reading, Causes and Remedies of Reading Failures, Reading Techniques & Strategies (Scanning, Skimming, Phrase reading, Intensive & Extensive reading, Exploiting the topic sentence for main ideas), Reading for details, Reading for evaluation and inference, Reading with questions - SQ3R, PR3, Methods for understanding difficult words in a reading text, Literature reading for study, analysis and comment.

Speaking & Communication Skills - Nature, Process & Development, Principles of Public Speech Making and Social Interaction, The Speech Sounds of English and their Articulation, Phonetic Transcription and Practical Speech Work.

Study Techniques - Choosing study centers and discussion groups, Note-taking during lectures, and from audio-visual equipment, Note-making techniques during private reading and literature search, Summary & Transcoding Techniques, Retrieving information from notes, The dictionary as a study guide.

Basic Research Methods & Term Paper Writing - Research – meaning & nature, Types & Methodology; Data in the Research Process, The Research Report, Process and Techniques, Documentation in Research Reports: Process, Types and Methods, Abbreviations in Research Reports, The term paper as a miniature research report, Practical term paper writing.

Course Evaluation & Grading - Students must attend at least 75% of the lectures to qualify for examination in the course.', '["Man, Society and Language - The Nature, Characteristics and Functions of Language, Human Communication & Language, World English, Levels and Varieties of English", "Vocabulary of English - Types, Method of Vocabulary Development, Synonyms, Antonyms, Homonyms, Acronyms, Paronyms, Affixation and other morphological processes", "Listening skill - Nature, Types, Purposes and Factors that affect Listening, Strategies and Aids for Effective Listening", "Reading Skill - Reading Problems, Levels and Types of Reading, Causes and Remedies of Reading Failures, Reading Techniques & Strategies, Reading for evaluation and inference", "Speaking & Communication Skills - Principles of Public Speech Making and Social Interaction, Phonetic Transcription and Practical Speech Work", "Study Techniques - Note-taking, Note-making, Summary & Transcoding Techniques", "Basic Research Methods & Term Paper Writing - The Research Report, Documentation, Abbreviations, practical term paper writing"]'::jsonb, 'Department of Mechanical Engineering handbook'),
  ('GSP 105', 'Natural Sciences I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('GSP 111', 'Use of Library and Study Skills', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'first', 2, 'Overview of Library: concepts, history, types and functions. Uses in academic libraries; organization of university library and library users. Library processes and procedures. Acquisition process, Cataloging and classification, LC Scheme, in-House Scheme, DDC. Serials process and circulation processes. Access tools in Library resources: Library catalogues, Indexes, Abstracts, Current contents information in the library. Reference sources: types of reference sources and services. Web resources and online resources. Overview of Databases, Online search strategies for information retrieval. Referencing and citation styles for information reporting. Concept of plagiarism. Learning skills and research skills, ICT skillsets: types of learning and information policies.', '["Overview of Library: concepts, history, types and functions. Uses in academic libraries; organization of university library and library users", "Library processes and procedures. Acquisition process, Cataloging and classification, LC Scheme, in-House Scheme, DDC. Serials process and circulation processes", "Access tools in Library resources: Library catalogues, Indexes, Abstracts, Current contents information", "Reference sources: types of reference sources and services. Web resources and online resources", "Overview of Databases, Online search strategies for information retrieval. Referencing and citation styles for information reporting. Concept of plagiarism", "Learning skills and research skills, ICT skillsets: types of learning and information policies"]'::jsonb, 'Department of Mechanical Engineering handbook'),
  ('ECO 101', 'Principles of Economics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'first', 2, 'Nature and significance of Economics; The methodology of economics; Economic tools of analysis; Theories of demand and supply; Elementary analysis; Dynamic theory of price; Elements of price theory; Production theory: Output, cost, law of diminishing returns; Market structure: Perfect competition, monopoly, oligopoly etc; Elementary theory of welfare economics; Determinants for and pricing of productive factors; Interest rate and profit.', '["Nature and significance of Economics", "The methodology of economics", "Economic tools of analysis", "Theories of demand and supply", "Elementary analysis", "Dynamic theory of price", "Elements of price theory", "Production theory: Output, cost, law of diminishing returns", "Market structure: Perfect competition, monopoly, oligopoly etc", "Elementary theory of welfare economics", "Determinants for and pricing of productive factors", "Interest rate and profit"]'::jsonb, 'Department of Economics handbook'),
  ('PSC 101', 'Introduction to Political Science', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'first', 2, 'The course introduces students to the nature of politics and how it is played; it emphasizes the issues of political discourse and practice; it also introduces students to the language and basic concepts of political science and other disciplines.', '["The course introduces students to the nature of politics and how it is played", "It emphasizes the issues of political discourse and practice", "It also introduces students to the language and basic concepts of political science and other disciplines"]'::jsonb, 'Department of Political Science handbook'),
  ('PSY 101', 'Principles of Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'first', 2, 'The Science of Psychology: History of Psychology Research methods in Psychology Fields of Psychology and other Disciplines. Biological Basis of Human Development.', '["The Science of Psychology: History of Psychology", "Research methods in Psychology", "Fields of Psychology and other Disciplines", "Biological Basis of Human Development"]'::jsonb, 'Department of Psychology handbook'),
  ('RCS 101', 'Introduction to Religion', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'first', 2, 'This course of study serves as a general introduction to the comparative study of major religious experiences, with special emphasis on common features found in religious beliefs and practices. The essence is to study religion as a universal phenomenon. It introduces students to the various definitions of religion from the sociological, cultural and psychological points of view. Keywords include theism, revelation, worship, sacred and profane, symbolism, taboos, myths, and religious language. Uses and abuses of religion in the society are considered.', '["This course of study serves as a general introduction to the comparative study of major religious experiences, with special emphasis on common features found in religious beliefs and practices", "The essence is to study religion as a universal phenomenon", "It introduces students to the various definitions of religion from the sociological, cultural and psychological points of view", "Keywords include theism, revelation, worship, sacred and profane, symbolism, taboos, myths, and religious language", "Uses and abuses of religion in the society are considered"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('SOC 102', 'Introduction to Sociology II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'second', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('GSP 102', 'The Use of English II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'second', 2, 'Part A: Basic Grammar: Introduction. The concept of grammar and its place in language teaching and learning. Parts of speech and their functions (treated in detail). Closed and open class items in parts of speech, Nominalization, Grammatical Structures: the phrase, the clause and the sentence. Elementary Clause Analysis, Sentence Types, Elements and Patterns. Agreement (Grammatical agreement, Notional agreement, Proximity agreement) Agreement with the correlatives. Direct and Reported Speech, Error typology identification and correction.

Part B: Varieties of writing. Introduction (The Meaning, Nature and Purpose of Writing, Writing Types or Genres and their Characteristics). The paragraph as the basic unit of an essay (Types, Development of the Paragraph, Methods of Paragraph Development, The thesis statement). Point of view and style in writing. Qualities of a good piece of writing: Form, Diction and Content in writing. The Mechanics of Writing: punctuation, spelling and capitalization.

Part C: Writing Genres - Planning and choosing your theme. Deciding your genre. Choosing and developing your plot. Point of view, setting and characterization. Using the language that works. Essay Writing — Narration, Description, Exposition and Argumentation. Technical Writing: Letter Writing, Memorandum Writing, Speech Writing, Agenda and Minutes, own story for practice, Computer-linked writing, types, style, language, and process.', '["Part A: Basic Grammar - The concept of grammar, Parts of speech, Grammatical Structures, Sentence Types, Agreement, Direct and Reported Speech, Error typology", "Part B: Varieties of writing - Meaning, Nature and Purpose of Writing, the paragraph as the basic unit of an essay, the thesis statement, Qualities of a good piece of writing, Mechanics of Writing", "Part C: Writing Genres - Planning and choosing your theme, plot, point of view, setting and characterization", "Essay Writing - Narration, Description, Exposition and Argumentation", "Technical Writing - Letter Writing, Memorandum Writing, Speech Writing, Agenda and Minutes"]'::jsonb, 'Department of Mechanical Engineering handbook'),
  ('GSP 106', 'Natural Science II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'second', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('ECO 102', 'Principles of Economics II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'second', 2, 'Elementary principles of macroeconomics and microeconomics; National income determination; The circular flow of income; Injections, withdrawals and the multiplier; Income determination; consumption, saving and investment functions; Nature and features of money; The banking system and the supply of money; Money supply and price level; International trade; Exchange rate and comparative advantage; Foreign trade and domestic economy; Economic growth; Elementary notion of economic planning; Introduction to Marxist economic theory.', '["Elementary principles of macroeconomics and microeconomics", "National income determination", "The circular flow of income; Injections, withdrawals and the multiplier", "Income determination; consumption, saving and investment functions", "Nature and features of money", "The banking system and the supply of money", "Money supply and price level", "International trade; Exchange rate and comparative advantage", "Foreign trade and domestic economy", "Economic growth", "Elementary notion of economic planning", "Introduction to Marxist economic theory"]'::jsonb, 'Department of Economics handbook'),
  ('PSC 102', 'Introduction to Political Science II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'second', 2, 'The course introduces students to the methods of Political Science, as well as the theory of knowledge; the relationship between political science and other disciplines.', '["The course introduces students to the methods of Political Science, as well as the theory of knowledge", "The relationship between political science and other disciplines"]'::jsonb, 'Department of Political Science handbook'),
  ('PSY 104', 'Determinants of Behaviour', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'second', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('RCS 142', 'Religion and Human Values', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '100 Level', 'second', 2, 'This course aims at emphasizing human dignity as opposed to more technological advantages man may accrue, important as they are, the population of religious traditions, oral or written which sanction this emphasis- Ethics of chauvinism and U.N. Human Rights.', '["This course aims at emphasizing human dignity as opposed to more technological advantages man may accrue, important as they are", "The population of religious traditions, oral or written which sanction this emphasis - Ethics of chauvinism and U.N. Human Rights"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('COS 101', 'Introduction to Computer Science', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'first', 2, 'Concepts of hardware and software; basic subsystems of a digital computer; characteristics of a digital computer; devices/media; types/classes of computer emphasising the PC; history of computers and their generations. Problem-solving: algorithm, flowchart, pseudocode, program/data, running a program. Programming: introduction to Java/BASIC programming language syntax and programming. Booting and shutdown; types of operating system; user interface; managing information, computer malware (virus, etc); computer network; internet and web usage, e-mail, instant messaging, etc. Office applications; use of a statistical package and a database management system.', '["Concepts of hardware and software","basic subsystems of a digital computer","characteristics of a digital computer","devices/media","types/classes of computer emphasising the PC","history of computers and their generations","Problem-solving: algorithm, flowchart, pseudocode, program/data, running a program","Programming: introduction to Java/BASIC programming language syntax and programming","Booting and shutdown","types of operating system","user interface","managing information, computer malware (virus, etc)","computer network","internet and web usage, e-mail, instant messaging, etc","Office applications","use of a statistical package and a database management system"]'::jsonb, 'Department of Computer Science course outline'),
