  ('PSY 241', 'Social Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'first', 2, 'Definition of social psychology. Psychology as a science. Social psychological assumptions. Social psychology and other social sciences. Socialization as the root of social behaviour. Attitude: definition, formation, functions and components.', '["Definition of social psychology. Psychology as a science. Social psychological assumptions", "Social psychology and other social sciences", "Socialization as the root of social behaviour", "Attitude: definition, formation, functions and components"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 251', 'Developmental Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Social Work', '200 Level', 'first', 2, 'This course offers topics on human growth and development from conception to adolescence. Areas to be covered include history and theories of child development, determinants of development, conception and the mechanism of heredity, cognitive, language, and personality development in infancy, early childhood and later childhood; physical and physiological changes at puberty; the meaning of identity in adolescence and adolescent behavioural problems.', '["This course offers topics on human growth and development from conception to adolescence", "Areas to be covered include history and theories of child development, determinants of development, conception and the mechanism of heredity", "Cognitive, language, and personality development in infancy, early childhood and later childhood", "Physical and physiological changes at puberty; the meaning of identity in adolescence and adolescent behavioural problems"]'::jsonb, 'Department of Psychology handbook'),
